module traffic_light(
    input rst_n, input clk, input pass_request,
    output [7:0] clock, output red, yellow, green
);
    // TODO: Please add your logic design here

    localparam idle = 2'd0;
    localparam s1_red = 2'd1;
    localparam s2_yellow = 2'd2;
    localparam s3_green = 2'd3;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;

    always@(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            state <= idle;
        end
        else begin
            case(state)
                idle: state <= s1_red;
                s1_red: state <= (cnt==3)? s3_green : s1_red;
                s2_yellow: state <= (cnt==3)? s1_red : s2_yellow;
                s3_green: state <= (cnt==3)? s2_yellow : s3_green;
            endcase
        end
    end


    always@(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            cnt <= 8'd10;
        end
        else begin
            if(pass_request && green && (cnt>10))
                cnt <= 8'd10;
            else begin
                if(!green && p_green)
                    cnt <= 8'd60;
                else if(!yellow && p_yellow)
                    cnt <= 8'd5;
                else if(!red && p_red)
                    cnt <= 8'd10;
                else 
                    cnt <= cnt - 8'd1;
            end
        end
    end

    always@(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            {p_red,p_yellow,p_green} <= 3'd0;
        end
        else begin
            {p_red,p_yellow,p_green} <= {red,yellow,green};
        end
    end

    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;
    assign clock = cnt;

endmodule
